import itertools
from collections import deque

def solve_small_v3(m):
    perms = list(itertools.permutations(range(m)))
    perm_to_idx = {p: i for i, p in enumerate(perms)}
    n = len(perms)

    adj = [[] for _ in range(n)]
    for i, p in enumerate(perms):
        for j in range(m):
            new_p = list(p)
            new_p[j], new_p[(j + 1) % m] = new_p[(j + 1) % m], new_p[j]
            adj[i].append(perm_to_idx[tuple(new_p)])

    dist = [[float('inf')] * n for _ in range(n)]
    for start_node in range(n):
        dist[start_node][start_node] = 0
        queue = deque([start_node])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[start_node][v] == float('inf'):
                    dist[start_node][v] = dist[start_node][u] + 1
                    queue.append(v)

    orbits = []
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            orbit = []
            curr = i
            while not visited[curr]:
                visited[curr] = True
                orbit.append(curr)
                p = perms[curr]
                rotated_p = (p[-1],) + p[:-1]
                curr = perm_to_idx[rotated_p]
            orbits.append(orbit)

    max_dist = 0
    for i in range(len(orbits)):
        for j in range(i, len(orbits)):
            min_d = float('inf')
            for u in orbits[i]:
                for v in orbits[j]:
                    if dist[u][v] < min_d:
                        min_d = dist[u][v]
            if min_d > max_dist:
                max_dist = min_d
    return max_dist

print(f"m=6: {solve_small_v3(6)}")

