import itertools
from collections import deque

def get_diameter_no_rotation(m):
    perms = list(itertools.permutations(range(m)))
    perm_to_idx = {p: i for i, p in enumerate(perms)}
    n = len(perms)

    adj = [[] for _ in range(n)]
    for i, p in enumerate(perms):
        for j in range(m):
            new_p = list(p)
            new_p[j], new_p[(j + 1) % m] = new_p[(j + 1) % m], new_p[j]
            adj[i].append(perm_to_idx[tuple(new_p)])

    max_dist = 0
    for start_node in range(n):
        dist = [-1] * n
        dist[start_node] = 0
        queue = deque([start_node])
        while queue:
            u = queue.popleft()
            if dist[u] > max_dist:
                max_dist = dist[u]
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
    return max_dist

for m in range(3, 7):
    print(f"m={m}: {get_diameter_no_rotation(m)}")
